class Solution { public: vector<int> numMovesStonesII(vector<int>& stones){sort(stones.begin(),stones.end());int n=stones.size(),maximum=max(stones[n-2]-stones[0],stones[n-1]-stones[1])-(n-2),minimum=n,left=0;for(int right=0;right<n;++right){while(stones[right]-stones[left]+1>n)++left;int count=right-left+1;minimum=min(minimum,count==n-1&&stones[right]-stones[left]==n-2?2:n-count);}return {minimum,maximum};} };
